-- GENERATED by `wfj generate` from data/gossip/gossip-46.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["460388c08a4afcf0"] = { "Ora sei pront<o/a> a seguire il sentiero che unisce la tua vita alla mia, anche se solo per poco. Dobbiamo però assicurarci che tu comprenda le cose di cui parlano gli spiriti.", "." },
  ["4604c89ae9e33346"] = { "Ti sorprende davvero? È così difficile credere che il potere di un Dio Antico possa arrivare persino dentro il Sogno? È vero: Eranikus, Tiranno del Sogno, muove guerra contro tutti noi. L'Incubo segue la scia della sua distruzione.", "." },
  ["460904535201b36d"] = { "Arnok fa delle bende ottime. Lo trovi alla capanna Survival of the Fittest, sulla riva del lago accanto alla Spirit Lodge, nella ⟦Valley of Spirits=Valle degli Spiriti⟧. È sopra la ⟦Valley of Strength=Valle della Forza⟧, verso ovest.", "." },
  ["460bc3d369626d65"] = { "I Sarkhoff... a volte i Sarkhoff vengono a trovarci. Sono brave persone.", "." },
  ["4611564be7160cd3"] = { "Proteggete il magistrato a ogni costo. Potrebbero arrivare da qualunque direzione!", "." },
  ["46195ba318452c14"] = { "Patetico...", "." },
  ["462f67778bbf9813"] = { "È morto! Khan Hratha è morto! E ora i ⟦Maraudine=Maraudon⟧ cadranno! Quando i Gelkis governeranno questa terra, {name}, ci ricorderemo di te. E gli spiriti della terra canteranno il tuo nome per sempre.", "." },
  ["463122705acb1ea2"] = { "I primi passi della nostra lotta contro il Flagello procedono bene. Abbiamo ottenuto alcuni successi, e spero che il mio aiuto possa servirti a portare nuovi successi in battaglia.", "." },
  ["46337db68f6ae336"] = { "Fermi! Infedeli!", "." },
  ["4633c6cd0479b3b4"] = { "Shenthul, ho perso il fischietto e non ho più razzi di segnalazione. Aiuto, ti prego!", "." },
  ["4635db1f6602bc29"] = { "Deve esserci un posto su Azeroth dove trovare melme non corrotte dal Flagello o da altro. Ma dove?!", "." },
  ["463891a88a5497bb"] = { "%s studia attentamente il biglietto di Sara Balloo ed emette un lungo, grave sospiro.", "." },
  ["463a3a7b23e6e874"] = { "<Benvenuto/Benvenuta> a ⟦Stormwind=Roccavento⟧! Faccio parte degli ufficiali della città e assisto la cittadinanza attraverso il nostro ufficio anagrafe. Se hai bisogno di rintracciare una persona in particolare, forse posso aiutarti. Grazie a metodi arcani e a una disciplina mentale affinata, riesco ad accedere a questi registri.\n\nSe hai affari da sbrigare con me, prego, procedi!", "." },
  ["463b55af7f4ca1ef"] = { "Oh, racconta! Basta la suspense a far urlare una ragazza!", "." },
  ["463f7593085c4832"] = { "Ti porto la prova delle mie gesta, Cyrus.", "." },
  ["4641f6a1582cfcfd"] = { "Buongiorno, Elling! Salve, Elaine! Dammi una forma di formaggio erborinato, eh?", "." },
  ["4642f9e280d27436"] = { "Hip hip, urrà!", "." },
  ["464728cfea218e38"] = { "Che storia avvincente. Ora capisco perché c'era tanta polvere su quel libro.", "." },
  ["464e73002c357179"] = { "Salute, {class}.\r\n\nSe lo desideri, posso mostrarti come intessere la magia attorno a te per cambiare l'aspetto del tuo equipaggiamento. Vuoi servirti dei miei servizi?", "." },
  ["4653241155467559"] = { "%s stringe il corpo inerte di Taelan Fordring e singhiozza piano.", "." },
  ["465ad121b64fa674"] = { "Parlami di Drek'Thar.", "." },
  ["465b376b5b71c1c2"] = { "Casa d'aste", "." },
  ["465ee02aae873533"] = { "Ti porterà l'idromele, ti porterà la birra...", "." },
  ["466531d166fe1893"] = { "Sì, sì, calmati, {class}, non c'è niente di cui preoccuparsi. Per fortuna, quando mi hai dato il pezzo sinistro la prima volta ho stabilito un legame con esso, quindi richiamarlo da dovunque tu l'abbia «smarrito» non è affatto un problema.\n\nEcco, e stavolta cerca di averne più cura.", "." },
  ["4666b2637a812f8b"] = { "Feugen fa contento padrone.", "." },
  ["46681fe26fe61cc8"] = { "Per la Legione! Per Kil'Jaeden!", "." },
  ["466da7e334d58034"] = { "Il Cannone Ultra Blastenheimer 5000 è un dispositivo di lancio monoposto all'avanguardia. Scaglia il suo carico quasi alla velocità di un drago ed è l'orgoglio della famiglia Blastenheimer, celebre in tutto il mondo per le sue imprese aeronautiche e combustibili!\n\nSe vuoi farti lanciare nei cieli per volare liber<o/a> come un uccello, cerca Maxima Blastenheimer all'estremità orientale della fiera. Ho sentito che ha piazzato un anello bersaglio laggiù sul ⟦Crystal Lake=Lago di Cristallo⟧, da centrare mentre veleggi nell'aria!", "." },
  ["467118502ac742f0"] = { "Ti insegnerò ciò che posso.", "." },
  ["467200e5a22989b0"] = { "Qui non c'è vittoria per voi! Quel poco terreno che avete guadagnato sarà inghiottito a suo tempo dall'esercito del Flagello!", "." },
  ["4673bb823e1fa495"] = { "Solo chi ha dimostrato di non essere ostile ai Mordilegno può attraversare il Rifugio senza timore di essere attaccato. Hai fatto qualcosa per guadagnarti la nostra fiducia, <straniero/straniera>?", "." },
  ["4678bfceaa9d14b4"] = { "Mio caro Staffron, hai dimenticato cosa significa amare? L'amore che un tempo condividevamo?", "." },
  ["467aaac6749652dc"] = { "I nostri nuovi alleati ci vendicheranno!", "." },
  ["467d77e3c3f70dcd"] = { "Ehi, tu! Se vuoi guadagnarti il rispetto dei ⟦Darkspear=Lanciascura⟧, puoi cominciare donando risorse preziose per chi ha bisogno! Tessuti e bende non crescono sugli alberi, sai.\n\nInvece di vendere i pezzi di stoffa che trovi durante le tue avventure, donali! Così ti guadagnerai il riconoscimento dei ⟦Darkspear=Lanciascura⟧!", "." },
  ["4684612f223b058f"] = { "Niente male... Immagino che addestrarti non sia fuori discussione. Molto bene! Cominciamo...", "." },
  ["4684b1e85683af72"] = { "Alexstrazsa, la Protettrice della Vita. Una creatura magnifica.", "." },
  ["4689f682fbd7d2c2"] = { "Hai messo il pezzo su un pesciolino e l'hai lasciato da qualche parte nelle acque del mare tra qui e i Regni Orientali? E questo pesciolino ha poteri speciali?", "." },
  ["468dc90bc2f8ff7d"] = { "Scoprire di più sulla mia situazione è stato quasi impossibile. Il contrabbandiere che ci aveva ingaggiati è sparito e Anthion Harmon, il capo della nostra compagnia di mercenari, è morto.", "." },
  ["468e523c2e1d50d4"] = { "Ora è il momento di attaccare! Per l'⟦Horde=Orda⟧!", "." },
  ["469a0a0c7901b8b9"] = { "Un paladino! Ucciderlo farebbe piacere al padrone. All'attacco!", "." },
  ["469b101ceeed2dfc"] = { "%s si mette in ginocchio.", "." },
  ["469b7eb2cd133a57"] = { "Parlami del capitano Galvangar.", "." },
  ["469d0d37a24495ac"] = { "Quindi sospetti che fosse coinvolto qualcuno dall'interno? Che li abbiano avvertiti?", "." },
  ["46a4c8d7573ba80c"] = { "Fanti, in riga!", "." },
  ["46b1ec976e8442fa"] = { "{name} ha difeso la segheria!", "." },
  ["46b575ae8ceb190d"] = { "Elisir miracolosi di Antonio Perelli in vendita!", "." },
  ["46bb88ca8d27f6b2"] = { "%s fa un cenno con il capo a {name} e sospira pensieroso.", "." },
  ["46bdccb7bb9d8016"] = { "Questo mi ricorda che presto dovrò trovare qualcosa da mangiare. Quanto a ciò che l'⟦Alliance=Alleanza⟧ sta cucinando, mi dicono che sono state confezionate $2092w alborelle iridate in carpione su $2093w. Inoltre sono stati preparati $2098w raptor arrosto su $2099w e $2101w pinnagialla maculati al vapore su $2103w, che ora sono in cella frigorifera in attesa di essere trasportati alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧.", "." },
  ["46c9f341733103e5"] = { "Ciò che ti offro ora è una di queste lame, non temprata, non scaldata, non trattata: la sua forma più grezza ed essenziale.\n\nOra devi solo trovare un drago che sia disposto a incantare la lama.\n\nSe avessi l'eternità davanti, potrebbe essere possibile; ma visto che sei mortale e potresti cessare di esistere da un momento all'altro, ti consiglierei di convincere uno dei draghi minori a fare ciò che chiedi.", "." },
  ["46cc26f3a7a684e4"] = { "Ce l'ho fatta! Grazie, dottore!", "." },
  ["46cc8ea879448798"] = { "Sei impazzit<o/a>? Non le hai viste le CREATURE SCHELETRICHE OSSUTE che ingombrano il paesaggio mentre venivi qui?\n\n<Rohan sospira.>\n\nSe ti piace stare all'aperto, troverai creature scheletriche in tutte le Terre Infette Occidentali e nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Fidati, non puoi non vederle: e loro di certo non ti mancheranno, se ne avranno l'occasione.\n\nSe preferisci le spedizioni, Stratholme e Scholomance sono senz'altro il posto giusto per i frammenti d'osso.", "." },
  ["46ced16d0a9e4a77"] = { "Come se la cavano i miei uomini?", "." },
  ["46d2470fcf20ea8d"] = { "Omen dorme nelle profondità del ⟦Lake Elune'ara=Lago Elune'ara⟧, ma può essere evocato sulle rive sud-orientali, vicino agli ⟦Stormrage Barrow Dens=Eremi di Grantempesta⟧. Lì troverai degli speciali lanciarazzi a grappolo...\n\nUsa i tuoi razzi nei lanciatori e arriveranno i servitori di Omen. Spara altri razzi, quasi tre dozzine, oppure lancia Candele di Elune contro i suoi servitori, e presto si risveglierà.", "." },
  ["46d6c747022e9f70"] = { "<Bentornato/Bentornata>, {name}.", "." },
  ["46dba375e735cdd7"] = { "Cosa ti porta al Castello di ⟦Stormwind=Roccavento⟧?", "." },
  ["46dda56ed395a41d"] = { "Affari ufficiali, John. Mi servono informazioni sul maresciallo Windsor. Parlami dell'ultima volta che l'hai visto.", "." },
  ["46e05c8a368e6f2d"] = { "Sì? Ho una corazza da finire, quindi sarà meglio che sia una cosa importante.", "." },
  ["46e49f5922cb0edb"] = { "L'ultima carica è piazzata. State indietro!", "." },
  ["46ef040c2944f77b"] = { "Anche se la costa di ⟦Darkshore=Rivafosca⟧ è più pericolosa di quella di Teldrassil, molti pescatori qui trovano di che guadagnare.", "." },
  ["46f0051871bd5b6a"] = { "Fate presto! Quando finisce, è finita! Prendete qui le vostre armi, subito!", "." },
  ["46f0a780f880dda6"] = { "Ho un sacco di cose da fare qui a ⟦Desolace=Desolanda⟧, {name}. Roetten vuole che raccogliamo dei reagenti per uno dei nostri clienti e che recuperiamo alcuni di questi oggetti smarriti.\n\nVisto che sei qui per dare una mano, perché non cominciamo?", "." },
  ["46f30266f8100ece"] = { "%s indica la pergamena a terra.", "." },
  ["46fac97e1fed0da7"] = { "Un'altra bella giornata nella giungla! Sarà una gran caccia, me lo sento. Appena Barnil avrà finito di pulire i fucili, porterò la battuta di caccia nel fitto delle liane intrecciate. Non è un brutto modo di passare la pensione per un vecchio veterano di guerra, eh?", "." },
  ["46ff34188b9e6fe2"] = { "Bene bene! Sei nel posto giusto per imparare l'Estrazione, <ragazzo/ragazza>! Geofram Bouldertoe in persona risiede alla Deepmountain Mining Guild. Non potresti chiedere un istruttore migliore di lui.", "." },
  ["46ff448296f5760b"] = { "%s esce dall'ombra per difendere il calderone!", "." },
})
